<script setup lang="ts">
import {ref,onMounted} from 'vue'
const props=defineProps<{contactId:number;leaseToken:string;blocked:boolean;request:(path:string,body?:any,method?:string)=>Promise<any>}>()
const emit=defineEmits<{saved:[revision:number]}>()
const data=ref<any>(null),values=ref<Record<string,any>>({}),busy=ref(false),error=ref(''),message=ref('')
async function load(){busy.value=true;error.value='';try{data.value=await props.request(`contacts/${props.contactId}/custom_fields/`);values.value={...Object.fromEntries(data.value.schema.fields.filter((f:any)=>f.active&&f.type==='boolean').map((f:any)=>[f.key,false])),...data.value.values}}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function save(){busy.value=true;error.value='';message.value='';try{const active=data.value.schema.fields.filter((f:any)=>f.active);const submitted=Object.fromEntries(active.map((field:any)=>[field.key,values.value[field.key]??null]));data.value=await props.request(`contacts/${props.contactId}/custom_fields/`,{revision:data.value.revision,schema_revision:data.value.schema.revision,token:props.leaseToken,values:submitted});values.value={...Object.fromEntries(data.value.schema.fields.filter((f:any)=>f.active&&f.type==='boolean').map((f:any)=>[f.key,false])),...data.value.values};emit('saved',data.value.revision);message.value='Champs métier enregistrés.'}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section><h3>Champs métier internes</h3><p v-if="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p><form v-if="data" @submit.prevent="save"><template v-for="field in data.schema.fields" :key="field.key"><label v-if="field.active">{{field.label}}{{field.required?' *':''}}<input v-if="field.type==='boolean'" v-model="values[field.key]" type="checkbox" :disabled="!leaseToken||blocked||busy"><select v-else-if="field.type==='choice'" v-model="values[field.key]" :required="field.required" :disabled="!leaseToken||blocked||busy"><option :value="null">Non renseigné</option><option v-for="choice in field.choices" :key="choice" :value="choice">{{choice}}</option></select><input v-else v-model="values[field.key]" :type="field.type==='date'?'date':'text'" :required="field.required" maxlength="2000" :disabled="!leaseToken||blocked||busy"></label><p v-else>{{field.label}} (archivé) : {{data.values[field.key]??'Non renseigné'}}</p></template><p v-if="!data.schema.fields.length">Aucun champ défini par l’administration.</p><p v-if="!leaseToken">Prenez en charge la fiche avant la saisie.</p><button class="primary" :disabled="!leaseToken||blocked||busy||!data.schema.fields.length">Enregistrer les champs métier</button></form><button class="secondary" :disabled="blocked||busy" @click="load">Recharger les champs</button></section></template>
<style scoped>form{display:grid;gap:16px;margin:20px 0}select{padding:12px;border:1px solid #dedfce;border-radius:8px}input[type=checkbox]{width:auto}</style>
